using QualityReporter.CSharp.Analysis.Axes; namespace QualityReporter.CSharp.Analysis;
public static class QualityScoresCalculator { public static void Calculate(List<FileResult> files,Config cfg){Percentiles.Set(files,x=>x.Metrics.Loc,(f,p)=>f.Risk.MethodSizePercentile=p);foreach(var f in files){double? P(double? x)=>x*100;var activity=new QualityAxisScore{Score=Math.Round(f.Activity.Score,1),Level=QualityAxisCalculator.Level(f.Activity.Score,true),AvailableWeight=100,Components=new(){{"change",P(f.Activity.ChangePercentile)??0},{"churn",P(f.Activity.ChurnPercentile)??0},{"recency",P(f.Activity.RecencyPercentile)??0},{"authors",P(f.Activity.AuthorPercentile)??0}}};var maintainability=new MaintainabilityRiskCalculator(cfg.QualityAxes.Maintainability).Calculate(new Dictionary<string,double?>{{"complexity",P(f.Risk.ComplexityPercentile)},{"rework",P(f.Risk.ReworkPercentile)},{"duplication",P(f.Risk.DuplicationRiskPercentile)},{"issues",P(f.Risk.IssuePercentile)},{"methodSize",P(f.Risk.MethodSizePercentile)}});var testability=new TestabilityRiskCalculator(cfg.QualityAxes.Testability).Calculate(new Dictionary<string,double?>{{"untestedComplexity",P(f.Metrics.UntestedComplexity?.Percentile)},{"lineCoverage",f.Metrics.LineCoverage.HasValue?100-f.Metrics.LineCoverage:null},{"branchCoverage",f.Metrics.BranchCoverage.HasValue?100-f.Metrics.BranchCoverage:null}});var architecture=new ArchitectureRiskCalculator(cfg.QualityAxes.Architecture).Calculate(new Dictionary<string,double?>{{"changeCoupling",P(f.Risk.CouplingRiskPercentile)},{"issues",P(f.Risk.IssuePercentile)}});f.Scores=new(){Activity=activity,Maintainability=maintainability,Testability=testability,Architecture=architecture};f.Scores.OverallQuality=OverallQualityRiskCalculator.Calculate(f.Scores,cfg.OverallRisk.Weights);if(f.Scores.OverallQuality.Score is double q){var priority=Math.Round(q*(.6+.4*f.Activity.EffectiveScore/100),1);f.Scores.HotspotPriority=new(){Score=priority,Level=QualityAxisCalculator.Level(priority),Components=new(){{"overallQuality",q},{"activity",f.Activity.EffectiveScore}},AvailableWeight=100};}}} }
